import numpy as np
params = np.array([2.0, 0.18, 1.20, 0.35, 1.0, 0.16, 0.18, 5.5, 2.2, 0.12, 12.0])
# invalid input: an evaluation time beyond the observation window must raise ValueError
def _catches_value_error(fn):
    try:
        fn()
    except ValueError:
        return np.array([1.0])
    return np.array([0.0])
assert np.allclose(_catches_value_error(lambda: seb_response(params.copy(), 0.7, np.array([2.0, 13.0]))), target)

